//! Emits `desktop/web/src/generated/command-map.ts` from `canopi_types::commands::ALL_COMMANDS`
//! (Stage 2 Item 10; `canopi-f47t.52.71`, `canopi-f47t.52.218`, `2.1-M411`).

use std::fmt::Write as _;

use canopi_types::commands::{ALL_COMMANDS, CommandSyncKind};

pub(crate) const COMMAND_MAP_OUTPUT: &str = "desktop/web/src/generated/command-map.ts";

const COMMAND_MAP_HEADER: &str = "\
// Generated by bindings-gen from canopi-types/src/commands.rs.
// Do not edit it by hand.
import type {
  AnalysisReceipt,
  AnalysisRequest,
  AppFolder,
  AppFolderLocations,
  CanopiFile,
  CommonNameEntry,
  DesignDraftSummary,
  DesignNotebookSection,
  DesignNotebookSnapshot,
  DesignSaveOutcome,
  DesignSummary,
  DialogKind,
  DynamicFilterOptions,
  FilterOptions,
  FlowerColorResolution,
  GeoResult,
  LibraryDeleteImpact,
  LibrarySnapshot,
  LidarDisplayDescriptor,
  LidarDisplayRequest,
  LidarImportCoverage,
  LidarImportReceipt,
  LidarLayerCollection,
  LidarSamplePointsRequest,
  LidarSampleSeries,
  LoadedDesign,
  OperationId,
  PaginatedResult,
  PickOpenOutcome,
  PickSaveOutcome,
  ProblemReportRequest,
  ProblemReportResult,
  ProcessingHistoryPage,
  RasterQuantity,
  ReadOnlyDesign,
  RecentDesignSummary,
  SavedObjectStamp,
  Settings,
  SpeciesDetail,
  SpeciesImage,
  SpeciesListItem,
  SpeciesSearchRequest,
  StoreId,
  SubsystemHealth,
  UpdateDownload,
  UpdateOffer,
} from './contracts'

export interface GeoJsonSource {
  readonly name: string
  readonly text: string
}

export interface PendingOpen {
  readonly path: string
  readonly several: boolean
}

export type CommandSyncKind = 'async' | 'bounded_sync'

";

pub(crate) fn render_typescript_command_map() -> String {
    let mut out = String::from(COMMAND_MAP_HEADER);
    out.push_str("export const COMMAND_NAMES = [\n");
    for row in ALL_COMMANDS {
        let _ = writeln!(out, "  '{}',", row.name);
    }
    out.push_str("] as const\n\n");
    out.push_str("export type CommandName = (typeof COMMAND_NAMES)[number]\n\n");

    out.push_str("export type CommandMap = {\n");
    for row in ALL_COMMANDS {
        if row.args.is_empty() {
            let _ = writeln!(
                out,
                "  readonly '{}': {{ readonly args: undefined; readonly reply: {} }}",
                row.name, row.reply
            );
        } else {
            let mut fields = String::new();
            for (index, arg) in row.args.iter().enumerate() {
                if index > 0 {
                    fields.push_str("; ");
                }
                if arg.optional {
                    let _ = write!(fields, "readonly {}?: {}", arg.name, arg.ts_type);
                } else {
                    let _ = write!(fields, "readonly {}: {}", arg.name, arg.ts_type);
                }
            }
            let _ = writeln!(
                out,
                "  readonly '{}': {{ readonly args: {{ {} }}; readonly reply: {} }}",
                row.name, fields, row.reply
            );
        }
    }
    out.push_str("}\n\n");

    out.push_str(
        "export type RawCommandInvoker = (\n  command: CommandName,\n  args: Record<string, unknown> | undefined,\n  operation: OperationId,\n) => Promise<unknown>\n\n",
    );
    out.push_str("/** Generated typed command invoker carrying a branded `OperationId` (2.1-M411, contracts §1). */\n");
    out.push_str("export function createTypedInvoke(raw: RawCommandInvoker) {\n");
    out.push_str("  return function call<K extends CommandName>(\n");
    out.push_str("    command: K,\n");
    out.push_str("    args: CommandMap[K]['args'],\n");
    out.push_str("    operation: OperationId,\n");
    out.push_str("  ): Promise<CommandMap[K]['reply']> {\n");
    out.push_str("    return raw(command, args as Record<string, unknown> | undefined, operation) as Promise<CommandMap[K]['reply']>\n");
    out.push_str("  }\n");
    out.push_str("}\n\n");

    out.push_str(
        "export const COMMAND_SYNC_KINDS: Readonly<Record<CommandName, CommandSyncKind>> = {\n",
    );
    for row in ALL_COMMANDS {
        let kind = match row.sync {
            CommandSyncKind::Async => "async",
            CommandSyncKind::BoundedSync => "bounded_sync",
        };
        let _ = writeln!(out, "  '{}': '{}',", row.name, kind);
    }
    out.push_str("} as const\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn renders_all_commands_from_canopi_types() {
        let ts = render_typescript_command_map();
        assert!(ts.starts_with("// Generated by bindings-gen"));
        assert!(ts.contains("'get_settings'"));
        assert!(ts.contains("'lidar_layer_collection'"));
        assert!(ts.contains("export type CommandMap"));
        assert!(ts.contains("export function createTypedInvoke"));
        assert!(ts.contains("readonly 'save_design': { readonly args: { readonly path: string; readonly content: Record<string, unknown>; readonly expectedFingerprint?: string | null }; readonly reply: DesignSaveOutcome }"));
    }
}
